import{_ as a,o as e,c as t,a0 as i}from"./chunks/framework.ZC3WYqLu.js";const k=JSON.parse('{"title":"JSON-LD, RDF Formats","description":"","frontmatter":{},"headers":[],"relativePath":"dev/fundamentals/json-ld-and-rdf-formats/index.md","filePath":"dev/fundamentals/json-ld-and-rdf-formats/README.md"}'),n={name:"dev/fundamentals/json-ld-and-rdf-formats/index.md"};function o(l,s,h,r,d,p){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="json-ld-rdf-formats" tabindex="-1">JSON-LD, RDF Formats <a class="header-anchor" href="#json-ld-rdf-formats" aria-label="Permalink to &quot;JSON-LD, RDF Formats&quot;">​</a></h1><p>CaSS uses <a href="https://json-ld.org/" target="_blank" rel="noreferrer">JSON-LD</a> for data storage. JSON-LD is a simple, light-weight data format that&#39;s also parsable as standard JSON. It exists to provide a standard for holding &#39;<strong>Linked Data</strong>&#39; (LD), which you can think of as meaning links to data (usually in place of the data itself) as values inside standard JSON objects.</p><p>JSON-LD is a compromise between rich data modeling formats such as <em>Turtle</em> and <em>RDF-JSON</em> and the much simpler, easier to use JSON. JSON-LD has many layers of complexity that should be unwrapped slowly. This guide will discuss a few of them necessary to use CASS.</p><h2 id="in-a-nutshell" tabindex="-1">In a Nutshell <a class="header-anchor" href="#in-a-nutshell" aria-label="Permalink to &quot;In a Nutshell&quot;">​</a></h2><p>A JSON-LD object is a JSON object that also holds</p><ol><li>A type (<code>@type</code>)</li><li>An identifier (<code>@id</code>)</li></ol><p><strong>JSON Object</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bob&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>JSON-LD Object</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:                  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://schema.org/Person&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:                    </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://dev.cassproject.org/api/data/Bob&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;http://schema.org/name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bob&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Keep in mind:</p><ul><li>All references to fields or objects in JSON-LD are URLs, instead of IDs or long pointers.</li><li>A JSON-LD object should be stored and retrievable at the location indicated by its <code>@id</code> (commonly just ‘<em>id</em>’).</li><li>Navigating to any URL should give you enough information to use the object.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>To make life simpler, the <code>@context</code> field either provides something similar to a namespace or a link to a document that describes a namespace. This has the benefit of providing meaning to things like shortened fields.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://schema.cassproject.org/0.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://schema.org/Person&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:      </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://dev.cassproject.org/api/data/Bob&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:     </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bob&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The field ‘name’ is specified by the namespace to mean ‘<a href="http://schema.org/name" target="_blank" rel="noreferrer">http://schema.org/name</a>’. These allow JSON-LD documents to be more tractable to developers.</p><h2 id="with-security" tabindex="-1">With Security <a class="header-anchor" href="#with-security" aria-label="Permalink to &quot;With Security&quot;">​</a></h2><p>CASS includes an extension to JSON-LD called <a href="/cass-editor/docs/dev/security/kbac-specification/">KBAC</a> that provides additional meta-fields (prefixed with <code>@</code>) that allow objects to be permissioned using Public Key Cryptography.</p><p>In short:</p><ul><li>The <code>@owner</code> field defines key-holders who can modify or delete an object</li><li>The <code>@reader</code> field defines key-holders who can read an object’s hidden and encrypted fields</li><li>The <code>@signature</code> field defines signatures that can be used to validate the integrity of the data</li></ul><p>These fields can be found in any CASS object, such as <a href="https://dev.cassproject.org/api/custom/data/schema.cassproject.org.0.2.Framework/76ffff33-bd15-4bf3-a007-4ce247d2216d/1495040497868" target="_blank" rel="noreferrer">this one</a>.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p>JSON-LD is aligned with <strong>RDF</strong>, which is an advanced data modeling paradigm and methodology that will not be covered here. Reading the JSON-LD specification is a good start, but the CASS Library attempts to insulate you from RDF as much as possible.</p><h2 id="other-rdf-formats" tabindex="-1">Other RDF Formats <a class="header-anchor" href="#other-rdf-formats" aria-label="Permalink to &quot;Other RDF Formats&quot;">​</a></h2><p>Other RDF formats may be negotiated through use of the Accept header in an HTTP GET request. Supported formats are:</p><blockquote><p>text/n4</p><p>text/turtle</p><p>application/x-turtle</p><p>application/rdf+xml</p><p>application/rdf+n4</p></blockquote>`,26)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
